<style>
  * { box-sizing: border-box; }
  body {
    font-family: -apple-system, "Helvetica Neue", Arial, sans-serif;
    margin: 0;
    padding: 0;
    color: #1d1d1f;
    background: #fff;
    font-size: 14px;
  }
